from pathlib import Path
from zipfile import ZipFile,ZIP_DEFLATED
import re,json,hashlib,fitz
root=Path('/mnt/data/gmri_dph_deliverables')
for stem in ['GMRI_DPH_Inside_Out_Research_Paper_2026-10-19','GMRI_DPH_Inside_Out_Engineering_Blueprint_2026-10-19']:
 s=(root/(stem+'.md')).read_text()
 used=set(re.findall(r'\[([GE]\d+)\]',s))
 if 'Research' in stem:
  defined=set(re.findall(r'^- \*\*\[([GE]\d+)\]\*\*',s,flags=re.MULTILINE))
  print('Bibliography',len(defined),'in-text',len(used),'undefined',sorted(used-defined))
 else:
  print('Blueprint footnote refs in companion paper:',sorted(used))
 blocks=re.findall(r'```json\n(.*?)\n```',s,flags=re.DOTALL)
 for idx,b in enumerate(blocks):
  try:json.loads(b)
  except Exception as e:print('INVALID JSON BLOCK',stem,idx,e)
 print(stem,'words',len(s.split()),'JSON blocks',len(blocks))
output=root/'GMRI_DPH_Paper_and_Blueprint_2026-10-19.zip'
with ZipFile(output,'w',ZIP_DEFLATED) as z:
 for f in sorted(root.iterdir()):
  if f.suffix in ('.pdf','.docx','.md') and f.name.startswith('GMRI_DPH_Inside_Out_'):
   z.write(f,f.name)
print('ZIP',output.name,'bytes',output.stat().st_size)
for f in sorted(root.iterdir()):
 print(hashlib.sha256(f.read_bytes()).hexdigest()[:16],f.name)
